async(page)=>{
const errors=[],checks=[];page.on('pageerror',e=>errors.push(e.message));const check=(v,s)=>{if(!v)throw Error(s);checks.push(s);};
await page.goto('http://127.0.0.1:5173/explorer.html');const creations=await page.evaluate(()=>VYSORA_DATA.creations);await page.context().grantPermissions(['clipboard-read','clipboard-write']);
for(const c of creations){await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:5173/fiche-creation.html?id='+c.id);await page.emulateMedia({reducedMotion:'reduce'});check(await page.locator('h1').textContent()===c.title,'Titre '+c.id);check(await page.locator('.author strong').textContent()===c.author,'Auteur '+c.id);check((await page.locator('.reproduce>.ai-tool').textContent()).replace(/[\s·]+/g,'')===c.config.replace(/[\s·]+/g,''),'Outils '+c.id);check(await page.locator('#useful-count').textContent()===String(c.useful),'Votes '+c.id);check(await page.locator('[data-try]').first().isVisible()===(c.type!=='projet'),'Reproduction selon le type '+c.id);check(await page.locator('img').evaluateAll(imgs=>imgs.every(i=>i.complete&&i.naturalWidth>0)),'Images '+c.id);
if(c.id!=='cite-ciel-mer'){check(!(await page.locator('#parcours').textContent()).includes('tours élancées au centre'),'Contenu propre '+c.id);await page.locator('.process-details summary').first().click();await page.locator('[data-step-copy]').first().click();check((await page.evaluate(()=>navigator.clipboard.readText())).length>30,'Copie étape '+c.id);}
await page.locator('#share').click();check((await page.evaluate(()=>navigator.clipboard.readText())).includes('id='+c.id),'Lien partagé '+c.id);
await page.locator('.image-open').click();check(await page.locator('#lightbox').evaluate(d=>d.open),'Aperçu '+c.id);await page.keyboard.press('Escape');
if(['keur-awa','ventes-boutique','portrait-gouache','factures-auto'].includes(c.id)){await page.evaluate(()=>scrollTo(0,0));await page.screenshot({path:'prototype/preview/fiche-'+c.id+'-desktop.png'});}
for(const width of [768,375,320]){await page.setViewportSize({width,height:900});check(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'Responsive '+c.id+' '+width);}
if(c.id==='ventes-boutique')await page.screenshot({path:'prototype/preview/fiche-projet-mobile.png'});
}
await page.goto('http://127.0.0.1:5173/fiche-creation.html?id=bissap');await page.locator('#save').click();await page.locator('#useful').click();await page.locator('#comment').fill('La lumière latérale révèle bien la couleur.');await page.locator('#comment-form .btn-primary').click();await page.locator('[data-try]').first().click();await page.locator('input[value="Réussi"]').check();await page.locator('#try-note').fill('La couleur du bissap est fidèle.');await page.locator('#try-form button').click();check(await page.locator('[data-repro-count]').first().textContent()==='1','Premier essai');check(!await page.locator('[data-success]').first().isVisible(),'Taux masqué sous trois essais');
await page.goto('http://127.0.0.1:5173/fiche-creation.html?id=portrait-gouache');check(await page.locator('#save').getAttribute('aria-pressed')==='false','Enregistrement indépendant');check(await page.locator('#comment-count').textContent()==='0','Commentaires indépendants');check(await page.locator('[data-repro-count]').first().textContent()==='18','Essais indépendants');
await page.goto('http://127.0.0.1:5173/fiche-creation.html?id=bissap');check(await page.locator('#save').getAttribute('aria-pressed')==='true','État conservé');check(await page.locator('#comment-count').textContent()==='1','Commentaire conservé');await page.evaluate(()=>localStorage.removeItem('vysora-bissap'));
await page.goto('http://127.0.0.1:5173/fiche-creation.html?id=absente');check((await page.locator('h1').textContent()).includes('introuvable'),'Identifiant inconnu');
await page.goto('http://127.0.0.1:5173/explorer.html');await page.locator('a[href="fiche-creation.html?id=keur-awa"]').first().click();await page.waitForURL('**/fiche-creation.html?id=keur-awa');check(true,'Navigation Explorer');
await page.setViewportSize({width:1440,height:1000});for(let y=0;y<await page.evaluate(()=>document.body.scrollHeight);y+=600){await page.evaluate(y=>scrollTo(0,y),y);await page.waitForTimeout(50);}await page.evaluate(()=>scrollTo(0,0));await page.screenshot({path:'prototype/preview/fiche-iteration-full.png',fullPage:true});check(errors.length===0,'Aucune erreur JavaScript');return{checks:checks.length,errors};
}

